/* ── 盘面 ──────────────────────────────────────────────────────── */

static int mode_screen(int m)
{
    switch (m) {
        case M_NAV: return SCR_NAV;
        case M_RECORD: return SCR_RECORD;
        case M_SET: return SCR_SETTINGS;
        default: return SCR_RIDE;
    }
}

static const char *mode_name(int m)
{
    static const char *const n[4] = { "骑行", "导航", "记录", "设置" };

    return n[m & 3];
}

static const char *mode_desc(int m)
{
    /* 底部提示条删掉后，把“按住 1 进入”并进盘心说明行：
     * 静态屏也能看出可长按，且不占底部。 */
    static const char *const d[4] = {
        "按住 1 进入 · 上次骑行", "按住 1 进入 · 转向提示",
        "按住 1 进入 · 数据回顾", "按住 1 进入 · 设备设置",
    };

    return d[m & 3];
}

static helm_icon_t mode_icon(int m)
{
    static const helm_icon_t ic[4] = {
        HELM_ICON_BIKE, HELM_ICON_NAV, HELM_ICON_RECORD, HELM_ICON_SETTINGS,
    };

    return ic[m & 3];
}

static void dial_tick_layout(int cx, int cy, int d)
{
    for (int i = 0; i < 24; i++) {
        const int deg = i * 15;
        const bool major = (i % 6 == 0);
        const double a = (double)deg * DEG2RAD;
        const double r1 = (major ? 66.0 : 69.0) * (double)d / 160.0;
        const double r2 = 74.0 * (double)d / 160.0;

        UD.tick_pts[i][0].x = cx + (int)lround(sin(a) * r1);
        UD.tick_pts[i][0].y = cy - (int)lround(cos(a) * r1);
        UD.tick_pts[i][1].x = cx + (int)lround(sin(a) * r2);
        UD.tick_pts[i][1].y = cy - (int)lround(cos(a) * r2);
        if (UD.tick[i] != NULL) {
            lv_line_set_points(UD.tick[i], UD.tick_pts[i], 2);
        }
    }
}

static void dial_pointer_layout(int angle)
{
    const double a = (double)angle * DEG2RAD;
    const double sx = sin(a);
    const double sy = -cos(a);
    const double px = cos(a);
    const double py = sin(a);
    const double sc = (double)UD.d / 160.0;
    const double r0 = 56.0 * sc;
    const double r1 = 84.0 * sc;
    const int x0 = UD.cx + (int)lround(sx * r0);
    const int y0 = UD.cy + (int)lround(sy * r0);
    const int x1 = UD.cx + (int)lround(sx * r1);
    const int y1 = UD.cy + (int)lround(sy * r1);
    const int cw = (int)lround(8.0 * sc);

    UD.ptr_pts[0].x = x0;
    UD.ptr_pts[0].y = y0;
    UD.ptr_pts[1].x = x1;
    UD.ptr_pts[1].y = y1;
    UD.cross_pts[0].x = x1 - (int)lround(px * cw);
    UD.cross_pts[0].y = y1 - (int)lround(py * cw);
    UD.cross_pts[1].x = x1 + (int)lround(px * cw);
    UD.cross_pts[1].y = y1 + (int)lround(py * cw);
    if (UD.ptr != NULL) {
        lv_line_set_points(UD.ptr, UD.ptr_pts, 2);
    }
    if (UD.cross != NULL) {
        lv_line_set_points(UD.cross, UD.cross_pts, 2);
    }
}

static void dial_geometry(int cx, int cy, int d, int fade)
{
    UD.cx = cx;
    UD.cy = cy;
    UD.d = d;

    if (UD.ring != NULL) {
        lv_obj_set_pos(UD.ring, cx - d / 2, cy - d / 2);
        lv_obj_set_size(UD.ring, d, d);
    }
    {
        lv_obj_t *arcs[6] = { UD.fill, UD.trk, UD.fill2, UD.trk2,
                              UD.lp_track, UD.lp_arc };

        for (int i = 0; i < 6; i++) {
            if (arcs[i] != NULL) {
                lv_obj_set_pos(arcs[i], cx - d / 2, cy - d / 2);
                lv_obj_set_size(arcs[i], d, d);
            }
        }
    }
    dial_tick_layout(cx, cy, d);
    dial_pointer_layout(s_angle);
    if (UD.hub != NULL) {
        lv_obj_set_style_opa(UD.hub, (lv_opa_t)fade, 0);
    }
    for (int i = 0; i < 4; i++) {
        if (UD.labels[i] != NULL) {
            lv_obj_set_style_opa(UD.labels[i], (lv_opa_t)fade, 0);
        }
    }
}

static void dial_sector(int mode, lv_opa_t opa, lv_obj_t **fill, lv_obj_t **trk)
{
    const int a = mode * 90 - 90;

    *fill = ARC(s_scr, UD.cx, UD.cy, UD.d, 24, a - 26, 52, C_LIGHT[mode],
                false, opa);
    *trk = ARC(s_scr, UD.cx, UD.cy, UD.d, 2, a - 26, 52, C_DEEP[mode], false,
               opa);
}

/* 标题行：文字严格按 120 居中；图标是文字左侧的“卫星”，不再把文字顶偏。
 * 采用方案 A：去掉色块，26px 图标按 30px 字的字面高取，直接放在文字左侧。 */
static void dial_title_layout(int mode)
{
    const int tw = text_width(mode_name(mode), PX_TITLE);
    const int left = 80 - tw / 2;   /* hub 宽 160，盘心 x=120 ⇒ 局部 80 */
    const int icon_cy = 19;         /* 30px CJK ink 中心：行盒顶 +19 */
    const int isz = 26;

    lv_obj_set_pos(UD.name, 0, 0);  /* 160 宽 + 居中 ⇒ 文字在 120 */
    if (UD.icon != NULL) {
        lv_obj_set_pos(UD.icon, left - 6 - isz, icon_cy - isz / 2);
    }
}

/* 主值：数字按 120 居中，单位挂在数字右侧并与数字共用基线。 */
static void hub_value_layout(void)
{
    const char *txt;
    const int y0 = 55;
    int tw;
    int x;

    if (UD.value == NULL) {
        return;
    }
    txt = lv_label_get_text(UD.value);
    tw = text_width(txt, PX_VALUE);
    x = 80 - tw / 2;
    lv_obj_set_x(UD.value, x);
    if (UD.unit != NULL) {
        lv_obj_set_x(UD.unit, x + tw + 3);
        place_baseline(UD.unit, PX_MICRO, y0 + base_off(PX_VALUE));
    }
}

static void dial_content(int mode)
{
    char buf[64];
    const int b = s_batt;

    if (UD.name == NULL) {
        return;
    }
    lv_label_set_text(UD.name, mode_name(mode));
    dial_title_layout(mode);
    lv_label_set_text(UD.desc, mode_desc(mode));
    hfi_set(UD.icon, mode_icon(mode));
    lv_obj_set_style_text_color(UD.icon, lv_color_hex(C_DEEP[mode]), 0);

    switch (mode) {
        case M_RIDE:
            snprintf(buf, sizeof(buf), "%.1f",
                     conv_dist(s_rec_n > 0 ? s_recs[0].dist : 42.6));
            break;
        case M_NAV:
            snprintf(buf, sizeof(buf), "%.1f", conv_dist(8.4));
            break;
        case M_RECORD:
            snprintf(buf, sizeof(buf), "%.1f", conv_dist(week_total()));
            break;
        default:
            snprintf(buf, sizeof(buf), "%d", b);
            break;
    }
    lv_label_set_text(UD.value, buf);
    lv_label_set_text(UD.unit, mode == M_SET ? "%" : unit_dist());
    hub_value_layout();

    switch (mode) {
        case M_RIDE:
            snprintf(buf, sizeof(buf), "本周 %.1f %s · 电量 %d%%",
                     conv_dist(week_total()), unit_dist(), b);
            break;
        case M_NAV:
            snprintf(buf, sizeof(buf), "全程 %.1f %s · 电量 %d%%",
                     conv_dist(10.0), unit_dist(), b);
            break;
        case M_RECORD:
            snprintf(buf, sizeof(buf), "本周 %d 次 · 电量 %d%%", week_rides(),
                     b);
            break;
        default:
            snprintf(buf, sizeof(buf), "固件 v1.2.6 · 电量 %d%%", b);
            break;
    }
    lv_label_set_text(UD.sub, buf);

    for (int i = 0; i < 4; i++) {
        const bool sel = (i == mode);

        lv_obj_set_style_text_font(UD.labels[i],
                                   F(sel ? PX_BODY : PX_SMALL), 0);
        lv_obj_set_style_text_color(UD.labels[i],
                                    lv_color_hex(sel ? P_INK : P_MUTE), 0);
    }
    s_shown_mode = mode;
}

static void dial_status_refresh(void)
{
    char buf[24];

    if (UD.gps_l == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%d", s_gps);
    lv_label_set_text(UD.gps_l, buf);
    snprintf(buf, sizeof(buf), "%d%%", s_batt);
    lv_label_set_text(UD.batt_l, buf);
    snprintf(buf, sizeof(buf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    lv_label_set_text(UD.time_l, buf);
    if (UD.live != NULL) {
        if (R.active) {
            lv_obj_remove_flag(UD.live, LV_OBJ_FLAG_HIDDEN);
            lv_obj_remove_flag(UD.live_bar, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(UD.live, LV_OBJ_FLAG_HIDDEN);
            lv_obj_add_flag(UD.live_bar, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

static void dial_build(void)
{
    memset(&UD, 0, sizeof(UD));
    s_screen = SCR_DIAL;
    d_bg(s_scr, P_PAPER);
    TOP(s_scr, "模式", "01 / 04");
    UD.top_l = lv_obj_get_child(s_scr, 0);
    UD.top_r = lv_obj_get_child(s_scr, 1);

    UD.cx = 120;
    UD.cy = 146;
    UD.d = 160;
    s_angle = s_mode * 90;
    UD.angle = s_angle;

    /* 整圈未选轨道 + 选中扇区（浅 20% + 深色 2px 外沿）。 */
    UD.ring = RING(s_scr, UD.cx, UD.cy, 160, 2, P_TRACK);
    dial_sector(s_mode, LV_OPA_COVER, &UD.fill, &UD.trk);

    /* 24 刻度：每 15°，整点 3px。 */
    for (int i = 0; i < 24; i++) {
        const bool major = (i % 6 == 0);

        UD.tick[i] = LINE(s_scr, UD.tick_pts[i], 2, major ? 3 : 1,
                          major ? P_INK : P_TICK);
    }
    /* 舵柄：中心到外圈 + 8px 横杆。 */
    UD.ptr = LINE(s_scr, UD.ptr_pts, 2, 3, P_INK);
