/** 扇段弧（只画 indicator；opa 用于转场半亮）。 */
static lv_obj_t *ARC(lv_obj_t *p, int cx, int cy, int d, int th, int start,
                     int span, uint32_t hex, bool rounded, lv_opa_t opa)
{
    lv_obj_t *arc = lv_arc_create(p);

    lv_obj_set_size(arc, d, d);
    lv_obj_set_pos(arc, cx - d / 2, cy - d / 2);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);
    lv_obj_set_style_arc_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 0, LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_MAIN);
    lv_obj_set_style_arc_opa(arc, opa, LV_PART_INDICATOR);
    lv_obj_set_style_arc_width(arc, th, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(hex), LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, rounded, LV_PART_INDICATOR);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);
    lv_arc_set_bg_angles(arc, ((start % 360) + 360) % 360,
                         (((start + span) % 360) + 360) % 360);
    lv_arc_set_rotation(arc, 0);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, 100);
    return arc;
}

/* lv_line 只保存点数组指针，不拷贝；栈上的临时数组出了函数就失效。
 * 这里统一把点拷进一块页面级池子（每次 rebuild 重置）。 */
#define PTS_POOL_MAX 512
static lv_point_precise_t s_pts_pool[PTS_POOL_MAX];
static int s_pts_n;

static void pts_reset(void)
{
    s_pts_n = 0;
}

static const lv_point_precise_t *PTS(const lv_point_precise_t *src, int n)
{
    if (s_pts_n + n > PTS_POOL_MAX) {
        s_pts_n = 0;
    }
    memcpy(&s_pts_pool[s_pts_n], src, (size_t)n * sizeof(s_pts_pool[0]));
    {
        const lv_point_precise_t *p = &s_pts_pool[s_pts_n];

        s_pts_n += n;
        return p;
    }
}

static lv_obj_t *LINE(lv_obj_t *p, const lv_point_precise_t *pts, int n,
                      int w, uint32_t hex)
{
    return d2_poly(p, PTS(pts, n), n, w, hex, true);
}

static void SET_ARC_OPA(lv_obj_t *o, int opa)
{
    if (o == NULL) {
        return;
    }
    if (opa < 0) opa = 0;
    if (opa > 255) opa = 255;
    lv_obj_set_style_arc_opa(o, (lv_opa_t)opa, LV_PART_INDICATOR);
}

static lv_obj_t *CHIP(lv_obj_t *p, int x, int y, int size, uint32_t light,
                      uint32_t deep)
{
    lv_obj_t *b = B(p, x, y, size, size, light, LV_OPA_COVER, 7);

    lv_obj_set_style_border_width(b, 1, 0);
    lv_obj_set_style_border_color(b, lv_color_hex(deep), 0);
    lv_obj_set_style_border_opa(b, LV_OPA_COVER, 0);
    return b;
}

static void TOP(lv_obj_t *p, const char *left, const char *right)
{
    /* 顶栏是“画框”层：左 12 / 右端 228；内容列仍是 24..216。 */
    L(p, left, PX_SMALL, P_MUTE, 12, 13);
    LW(p, right, PX_SMALL, P_MUTE, 120, 13, 108, LV_TEXT_ALIGN_RIGHT);
}

/* ── 基线 / 光学对齐小工具 ─────────────────────────────────────
 * FreeType 的 label y 是行盒顶，不是基线；直接按 y 摆 22px 数字和 11px
 * 单位会让单位浮在基线上方 3~6px。这里统一用 font->base_line 求基线。 */
static int base_off(int px)
{
    lv_font_t *f = F(px);

    return lv_font_get_line_height(f) - f->base_line;
}

/** 把 label 的行盒放到基线 baseline 上。 */
static void place_baseline(lv_obj_t *l, int px, int baseline)
{
    lv_obj_set_y(l, baseline - base_off(px));
}

/** 文字 advance 宽度（不是 ink 框；居中按排版宽度算）。 */
static int text_width(const char *txt, int px)
{
    lv_point_t sz;

    lv_txt_get_size(&sz, txt, F(px), 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    return (int)sz.x;
}

/** 临时提示：只在长按/toast 时创建；静态屏没有这条。 */
static void hint_set(const char *txt)
{
    if (s_hint == NULL) {
        s_hint = LW(s_scr, txt, PX_MICRO, P_MUTE, 0, 302, 240,
                    LV_TEXT_ALIGN_CENTER);
    } else {
        lv_label_set_text(s_hint, txt);
    }
}

static void hint_clear(void)
{
    if (s_hint != NULL) {
        lv_obj_delete(s_hint);
        s_hint = NULL;
    }
}

static void toast(const char *msg)
{
    /* 巡页取证：toast 会在同一帧的数据定时器里重新出现，证据图里不要。 */
    if (s_tour_dir[0] != '\0') {
        s_toast_until = 0;
        hint_clear();
        return;
    }
    snprintf(s_toast_msg, sizeof(s_toast_msg), "%s", msg);
    s_toast_until = lv_tick_get() + 1400;
    hint_set(msg);
}

