static const char *lp_verb(void)
{
    switch (LP.target) {
        case LP_ENTER:
            return mode_name(s_mode);
        case LP_ACTIVATE:
            if (SL.sel >= 0 && SL.sel < SL.nrow) {
                const set_item_t *it = &SL.items[SL.item_of_row[SL.sel]];

                if (it->act >= SA_ENTER_DISPLAY && it->act <= SA_ENTER_SCAN) {
                    return "进入";
                }
                return "调节";
            }
            return "调节";
        case LP_PAUSE:
            if (!R.active) {
                return "开始骑行";
            }
            return R.paused ? "继续" : "暂停";
        case LP_END_RIDE:
            return "结束骑行";
        case LP_NAV_CTRL:
            return s_nav_active ? "本次导航" : "海拔";
        case LP_GRADE_ZERO:
            return "归零";
        case LP_TOGGLE_RIDE:
            return R.active ? "进入骑行" : "开始骑行";
        default:
            return "";
    }
}

