static void dial_rotate_next(void)
{
    int from_mode;
    int to_mode;
    int a0;
    int target;
    int duration = 160;
    lv_anim_t a;

    /* 转场中禁止再转；但盘面旋转本身可以被下一次 KEY1 打断（#2）。 */
    if (UD.fill == NULL || (s_busy && s_tr_anim != NULL)) {
        return;
    }
    a0 = (int)s_angle;

    if (s_rot_anim != NULL) {
        /* ANIMATION #2：从当前角重定目标，120ms；旧 B 升为 A。 */
        lv_anim_delete(&s_rot_p, NULL);
        s_rot_anim = NULL;
        if (UD.fill != NULL) {
            lv_obj_delete(UD.fill);
            lv_obj_delete(UD.trk);
        }
        UD.fill = UD.fill2;
        UD.trk = UD.trk2;
        UD.fill2 = NULL;
        UD.trk2 = NULL;
        from_mode = s_rot_to_mode;
        s_rot_oa0 = s_rot_oa_cur;
        s_rot_ob0 = s_rot_ob_cur;
        s_mode = from_mode;
