    to_mode = (from_mode + 1) % M_COUNT;

    target = to_mode * 90;
    while (target <= a0) {
        target += 360;
    }

    s_rot_a0 = a0;
    s_rot_a1 = target;
    s_rot_from_mode = from_mode;
    s_rot_to_mode = to_mode;
    s_rot_swapped = false;
